package com.macro.mall.operations.dao;
import java.util.*;
import org.apache.ibatis.annotations.*;
public interface HandoffSummaryDao {
 @Update("UPDATE ai_handoff_problem SET index_state=#{state} WHERE case_ref=#{ref} AND deleted_at IS NULL AND quality='INSUFFICIENT_CONTEXT'") int indexWaiting(@Param("ref") String ref,@Param("state") String state);
 @Update("UPDATE ai_handoff_summary SET state='PENDING',error_code=NULL,updated_at=UTC_TIMESTAMP() WHERE case_ref=#{ref} AND state='FAILED' AND attempts<2 AND summary_version=#{version} AND snapshot_json IS NOT NULL") int retry(@Param("ref") String ref,@Param("version") int version);
 @Select("SELECT s.case_ref AS caseRef,s.input_hash AS inputHash,s.input_version AS inputVersion,s.snapshot_json AS snapshot FROM ai_handoff_summary s JOIN ai_handoff_problem p ON p.case_ref=s.case_ref WHERE p.deleted_at IS NULL AND s.attempts<2 AND (s.state='PENDING' OR (s.state='RUNNING' AND s.lease_until<UTC_TIMESTAMP())) ORDER BY s.created_at LIMIT 1 FOR UPDATE") Map<String,Object> next();
 @Update("UPDATE ai_handoff_summary SET state='FAILED',error_code='lease_attempts_exhausted',lease_ref=NULL WHERE state='RUNNING' AND lease_until<UTC_TIMESTAMP() AND attempts>=2") int exhausted();
 @Update("UPDATE ai_handoff_summary SET state='RUNNING',attempts=attempts+1,lease_ref=#{lease},lease_until=DATE_ADD(UTC_TIMESTAMP(),INTERVAL 90 SECOND),updated_at=UTC_TIMESTAMP() WHERE case_ref=#{ref}") int lease(@Param("ref") String ref,@Param("lease") String lease);
 @Select("SELECT s.case_ref AS caseRef,s.input_hash AS inputHash,s.input_version AS inputVersion,s.snapshot_json AS snapshot,s.summary_version AS summaryVersion,s.state,s.summary_json AS summary,s.review_state AS reviewState,s.error_code AS errorCode,s.model_version AS modelVersion FROM ai_handoff_summary s JOIN ai_handoff_problem p ON p.case_ref=s.case_ref WHERE s.case_ref=#{ref} AND p.deleted_at IS NULL") Map<String,Object> get(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_summary SET state=#{state},summary_json=#{summary},summary_version=summary_version+1,model_version=#{model},prompt_version='handoff-summary-v2',error_code=#{error},review_state='AI_UNREVIEWED',lease_ref=NULL,updated_at=UTC_TIMESTAMP() WHERE case_ref=#{ref} AND input_hash=#{hash} AND input_version=#{inputVersion} AND state='RUNNING' AND lease_ref=#{lease} AND lease_until>UTC_TIMESTAMP()") int finish(Map<String,Object> q);
 @Update("UPDATE ai_handoff_problem SET projection_json=#{projection},projection_hash=#{projectionHash},quality=#{quality},template_version='summary-v1',version=version+1,index_state=IF(#{quality}='READY','PENDING','INSUFFICIENT_CONTEXT'),attempts=0,lease_ref=NULL WHERE case_ref=#{ref} AND deleted_at IS NULL") int publish(Map<String,Object> q);
 @Update("UPDATE ai_handoff_summary SET state='DELETED',snapshot_json=NULL,summary_json=NULL,lease_ref=NULL,updated_at=UTC_TIMESTAMP() WHERE case_ref=#{ref}") int clear(@Param("ref") String ref);
 @Update("UPDATE ai_handoff_summary SET summary_json=#{summary},summary_version=summary_version+1,review_state='HUMAN_REVIEWED',updated_at=UTC_TIMESTAMP() WHERE case_ref=#{ref} AND state='SUCCEEDED' AND summary_version=#{version}") int correct(Map<String,Object> q);
 @Insert("INSERT INTO ai_handoff_summary_audit(case_ref,version,source,actor_ref,input_hash,created_at) SELECT case_ref,summary_version,#{source},#{actor},input_hash,UTC_TIMESTAMP() FROM ai_handoff_summary WHERE case_ref=#{ref}") int audit(@Param("ref") String ref,@Param("source") String source,@Param("actor") String actor);
 @Update("UPDATE ai_handoff_group_analysis a JOIN ai_handoff_analysis_source s ON s.analysis_ref=a.analysis_ref SET a.state='STALE',a.lease_ref=NULL WHERE s.case_ref=#{ref} AND a.state<>'CLEARED'") int invalidate(@Param("ref") String ref);
}
